SELECT id, doctor_id, schedule_date, period, start_time, end_time,
       total_slots, booked_count, extra_slots, status, template_id, created_at, updated_at
FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date >= #{startDate}
  AND schedule_date <= #{endDate}

SELECT id, doctor_id, schedule_date, period, start_time, end_time,
       total_slots, booked_count, extra_slots, status, template_id, created_at, updated_at
FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND period = #{period}
  AND status = 'ACTIVE'
